(ns fastmath.ml.regression-test
  (:require [fastmath.ml.regression :as sut]
            [clojure.test :as t]
            [fastmath.core :as m]
            [clojure.pprint]
            [fastmath.vector :as v]
            [fastmath.matrix :as mat]
            [fastmath.ml.regression.contrast :as contrast]
            [clojure.edn :as edn]
            [clojure.java.io :as io]))

;; §2.2: shared, memoized EDN reference loader -- all R-fitted reference
;; values live in `test/resources/regression/*_reference.edn` (generated by
;; `fastmath.dev.regression-ref-gen`), so no live R session is needed to run
;; this test suite.

(def ^:private load-ref
  "Load and parse one `test/resources/regression/<name>_reference.edn` file.
  Memoized: each file is read and parsed at most once per test run,
  regardless of how many deftests/calls reference it."
  (memoize
   (fn [name]
     (-> (str "regression/" name "_reference.edn")
         io/resource
         slurp
         edn/read-string))))

;; §2.3: `col` is a raw categorical column (a seq of keywords); `values` are
;; the non-reference levels to build 0/1 columns for, matching the original
;; tablecloth `one-hot`'s calling convention. The reference level is
;; whichever level of `col` is not in `values`. Delegates to `contrast/dummy`;
;; duplicated (not shared) with the generator's own copy, per §4.

(defn- one-hot
  [col values]
  (let [levels (distinct col)
        reference (first (remove (set values) levels))
        coding (contrast/dummy (cons reference values))
        columns (apply map vector (map (:mapping coding) col))]
    (zipmap values columns)))

;; §2.3 extension: `col1`/`col2` are raw categorical columns. Reproduces the
;; original tablecloth `mult-columns`' exact column order and default
;; (first-appearance, sort1?/sort2?=false) reference-level convention.

(defn- mult-columns
  [col1 col2]
  (let [cs1 (vec (rest (distinct col1)))
        cs2 (vec (rest (distinct col2)))
        oh1 (one-hot col1 cs1)
        oh2 (one-hot col2 cs2)
        onehot1-cols (map oh1 cs1)
        onehot2-cols (map oh2 cs2)
        interactions (for [c2 cs2 c1 cs1] (mapv * (oh1 c1) (oh2 c2)))]
    {:cs1 cs1 :cs2 cs2 :xss (apply map vector (concat onehot1-cols onehot2-cols interactions))}))

;; §2.4 (superseded): `add-poly` (a pure-fastmath port wrapping
;; `v/orthonormal-polynomials`) has been replaced at both its call sites
;; (`deposit-data`, `danishlc-data`) by `sut/polynomial-transformer`, used via
;; the model's own `:transformer` option -- unlike `add-poly`, it is a genuine
;; fitted closure that can be evaluated at *new* x values, enabling a
;; newdata-predict check for both poly-encoded deftests. See the topic note
;; "Fastmath Regression Test R and Tablecloth Removal" (Continuation).

;; §3.1: named comparators, fine-grained -- each performs one `t/is` per field.
;; Shared between LM and GLM (identical shape on both sides):

(defn- check-coefficients
  "3.1.1. `coefs` = (:coefficients lm-or-glm), a seq of per-coefficient maps.
  `ref` = {:estimate [...] :stderr [...] :t-value|:z-value [...] :p-value [...]}.
  Reads whichever of :t-value/:z-value `ref` carries."
  [coefs ref]
  (t/is (v/delta-eq (map :estimate coefs) (:estimate ref)))
  (t/is (v/delta-eq (map :stderr coefs) (:stderr ref)))
  (let [stat-key (if (contains? ref :t-value) :t-value :z-value)]
    (t/is (v/delta-eq (map stat-key coefs) (stat-key ref))))
  (t/is (v/delta-eq (map :p-value coefs) (:p-value ref))))

(defn- check-xtxinv
  "3.1.2."
  [xtxinv ref]
  (t/is (v/delta-eq (mat/mat->seq xtxinv) ref)))

(defn- check-correlation
  "3.1.3. `correlation` = (:correlation analysis), a matrix; `ref` is flat."
  [correlation ref]
  (t/is (v/delta-eq (flatten correlation) ref)))

(defn- check-leverage
  "3.1.4."
  [leverage ref]
  (t/is (v/delta-eq (:hat leverage) (:hat ref)))
  (t/is (v/delta-eq (:sigmas leverage) (:sigmas ref)))
  (t/is (v/delta-eq (flatten (:coefficients leverage)) (:coefficients ref))))

(defn- check-influence
  "3.1.5. Optional `cooks-tol` (GLM uses 1e-5, LM uses the default)."
  ([influence ref] (check-influence influence ref nil))
  ([influence ref cooks-tol]
   (t/is (if cooks-tol
           (v/delta-eq (:cooks-distance influence) (:cooks-distance ref) cooks-tol)
           (v/delta-eq (:cooks-distance influence) (:cooks-distance ref))))
   (t/is (v/delta-eq (:dffits influence) (:dffits ref)))
   (t/is (v/delta-eq (:covratio influence) (:covratio ref)))
   (t/is (v/delta-eq (flatten (:dfbetas influence)) (:dfbetas ref)))))

(defn- check-df
  "3.1.6. Key-presence tolerant: checks whichever keys `ref` carries
  (LM: :residual/:model, GLM: :residual/:null)."
  [df ref]
  (doseq [k (keys ref)]
    (t/is (== (get df k) (get ref k)))))

(defn- check-ll
  "3.1.7. Key-presence tolerant (LM carries extra :aic-rss/:bic-rss)."
  [ll ref]
  (doseq [k (keys ref)]
    (t/is (m/delta-eq (get ll k) (get ref k)))))

;; LM-specific:

(defn- check-residuals-lm
  "3.1.8."
  [residuals ref]
  (t/is (v/delta-eq (:raw residuals) (:raw ref)))
  (t/is (v/delta-eq (:weighted residuals) (:weighted ref))))

(defn- check-fit-lm
  "3.1.9."
  [lm ref]
  (t/is (v/delta-eq (:fitted lm) (:fitted ref)))
  (t/is (m/delta-eq (:sigma lm) (:sigma ref)))
  (t/is (m/delta-eq (:sigma2 lm) (:sigma2 ref)))
  (t/is (m/delta-eq (:r-squared lm) (:r-squared ref)))
  (t/is (m/delta-eq (:adjusted-r-squared lm) (:adjusted-r-squared ref)))
  (t/is (m/delta-eq (:f-statistic lm) (:f-statistic ref))))

(defn- check-normality
  "3.1.10."
  [normality ref]
  (t/is (m/delta-eq (:skewness normality) (:skewness ref)))
  (t/is (m/delta-eq (:kurtosis normality) (:kurtosis ref)))
  (t/is (m/delta-eq (get-in normality [:durbin-watson :raw]) (:durbin-watson ref))))

(defn- check-analysis-residuals-lm
  "3.1.11."
  [residuals ref]
  (t/is (v/delta-eq (:standardized residuals) (:standardized ref)))
  (t/is (v/delta-eq (:studentized residuals) (:studentized ref))))

;; New-data prediction (fit/stderr/confidence-interval), shared by LM and GLM.
;; `model` is a fitted `LMData`/`GLMData` (implements `IFn`); `newdata-xss` is
;; a seq of points ready to pass straight to `model`/`sut/predict` as-is (i.e.
;; already offset-prepended, matching `with-offset`'s convention, when the
;; model was fit with an offset -- `predict`'s own `:transformer` application
;; happens internally, after offset extraction). `ref` = {:fit [...] :stderr
;; [...] :confidence-interval [[lo hi] ...]}, generated by
;; `fastmath.dev.regression-ref-gen`'s `predict-lm-oracle`/`predict-glm-oracle`.
(defn- check-predict
  [model newdata-xss ref]
  (let [preds (map #(model % true) newdata-xss)]
    (t/is (v/delta-eq (map :fit preds) (:fit ref)))
    (t/is (v/delta-eq (map :stderr preds) (:stderr ref)))
    (t/is (v/delta-eq (mapcat :confidence-interval preds) (flatten (:confidence-interval ref))))))

(def ys [1 2.1 3.2 4 4.9 5.5 10 7 8.1 8.7])
(def nys (v/normalize ys))
(def xss-1 '(-0.5 -1 -2 -3 -4 -5 -6 -7 -8 -9))
(def xss-2 '(1 2 0 2 1 0 1 2 0 2))
(def xss-3 (v/emult xss-1 xss-2))
(def xss (map vector xss-1 xss-2 xss-3))
(def weights [2 1 2 1 2 1 2 1 2 1])
(def offset (range 10))

;; New-data prediction points for basic-lm/dummy-data/gaussian-glm (Tier 1) --
;; two points outside the training x1/x2/offset ranges (x1 in [-9,-0.5], x2 in
;; {0,1,2}, offset in [0,9]), matching `fastmath.dev.regression-ref-gen`'s
;; `basic-new-x1`/`basic-new-x2`/`basic-new-off` exactly. Each point is a
;; [x1 x2 x1*x2] triple, matching `xss`'s own pre-multiplied interaction
;; column (fastmath has no formula support -- the interaction is a literal
;; third column here, same as `xss`/`xss-3` above).
(def new-xss [[-10.0 1.0 -10.0] [-0.3 2.0 -0.6]])
(def new-offset [10.0 11.0])
(defn- with-new-offset
  "Prepend `new-offset` to each of `new-xss`, matching `with-offset`'s
  `[offset x1 x2 ...]` convention."
  [] (map cons new-offset new-xss))

(defn- lm-tests
  "§3.2. `ref-block` is an already-resolved {:model :analysis} map (the
  deftest call site owns loading and, for multi-call files, sub-key
  selection -- decouples this fn from I/O). `options` may carry a test-only
  `:newdata-xss` key (a seq of new-data points, see `check-predict`) -- it is
  passed straight through to `sut/lm` alongside the real fitting options,
  which simply ignores unknown keys, matching `glm-tests`' own
  `:no-analysis?`/`:qres?` convention."
  ([ys xss ref-block] (lm-tests ys xss nil ref-block))
  ([ys xss options ref-block]
   (let [lm (sut/lm ys xss options)
         analysis (sut/analysis lm)]
     (t/is (m/delta-eq (:intercept lm) (get-in ref-block [:model :intercept])))
     (t/is (v/delta-eq (:beta lm) (get-in ref-block [:model :beta])))
     (check-coefficients (:coefficients lm) (get-in ref-block [:model :coefficients]))
     (check-xtxinv (:xtxinv lm) (get-in ref-block [:model :xtxinv]))
     (check-df (:df lm) (get-in ref-block [:model :df]))
     (check-ll (:ll lm) (get-in ref-block [:model :ll]))
     (check-fit-lm lm (:model ref-block))
     (check-residuals-lm (:residuals lm) (get-in ref-block [:model :residuals]))
     (check-correlation (:correlation analysis) (get-in ref-block [:analysis :correlation]))
     (check-normality (:normality analysis) (get-in ref-block [:analysis :normality]))
     (check-analysis-residuals-lm (:residuals analysis) (get-in ref-block [:analysis :residuals]))
     (check-leverage (:leverage analysis) (get-in ref-block [:analysis :leverage]))
     (check-influence (:influence analysis) (get-in ref-block [:analysis :influence]))
     (when-let [predict-ref (get-in ref-block [:extra :predict])]
       (check-predict lm (:newdata-xss options) predict-ref)))))

(t/deftest basic-weights-intercept
  (lm-tests ys xss {:weights weights :newdata-xss new-xss} (load-ref "basic-weights-intercept")))

(t/deftest basic-weights-intercept-transformer
  (lm-tests ys xss {:weights weights :transformer (fn [[a b c]] [(m/exp a) a b c]) :newdata-xss new-xss}
                (load-ref "basic-weights-intercept-transformer")))

(t/deftest basic-weights-intercept-offset
  (lm-tests ys xss {:weights weights :offset offset :newdata-xss (with-new-offset)}
                (load-ref "basic-weights-intercept-offset")))

(t/deftest basic-weights-no-intercept
  (lm-tests ys xss {:weights weights :intercept? false :newdata-xss new-xss} (load-ref "basic-weights-no-intercept")))

(t/deftest basic-weights-no-intercept-offset
  (lm-tests ys xss {:weights weights :intercept? false :offset offset :newdata-xss (with-new-offset)}
                (load-ref "basic-weights-no-intercept-offset")))

(t/deftest basic-no-weights-intercept
  (lm-tests ys xss {:newdata-xss new-xss} (load-ref "basic-no-weights-intercept")))

(t/deftest basic-no-weights-intercept-offset
  (lm-tests ys xss {:offset offset :newdata-xss (with-new-offset)} (load-ref "basic-no-weights-intercept-offset")))

(t/deftest basic-no-weights-no-intercept
  (lm-tests ys xss {:intercept? false :newdata-xss new-xss} (load-ref "basic-no-weights-no-intercept")))

(t/deftest basic-no-weights-no-intercept-offset
  (lm-tests ys xss {:intercept? false :offset offset :newdata-xss (with-new-offset)}
                (load-ref "basic-no-weights-no-intercept-offset")))

;; GLM-specific comparators (§3.1.12-3.1.16, 3.1.19). `check-coefficients`,
;; `check-xtxinv`, `check-correlation`, `check-leverage`, `check-influence`,
;; `check-df`, `check-ll` above are already shared with LM.

(defn- check-residuals-glm
  "3.1.12."
  [residuals ref]
  (t/is (v/delta-eq (:working residuals) (:working ref) 1.0e-5))
  (t/is (v/delta-eq (:deviance residuals) (:deviance ref)))
  (t/is (v/delta-eq (:pearson residuals) (:pearson ref)))
  (t/is (v/delta-eq (:raw residuals) (:raw ref) 1.0e-4)))

(defn- check-fit-glm
  "3.1.13. :deviance :null is deliberately NOT checked here -- the original
  glm-tests only compares it when :compare-deviance-null? is explicitly true
  (default false), so that gate lives at the glm-tests call site instead."
  [glm ref]
  (t/is (v/delta-eq (:fitted glm) (:fitted ref) 1.0e-4))
  (t/is (m/delta-eq (:dispersion glm) (:dispersion ref)))
  (t/is (m/delta-eq (get-in glm [:deviance :residual]) (get-in ref [:deviance :residual]))))

(defn- check-weights
  "3.1.14."
  [weights ref]
  (t/is (v/delta-eq (:weights weights) (:weights ref)))
  (t/is (v/delta-eq (:initial weights) (:initial ref))))

(defn- check-analysis-residuals-glm
  "3.1.15."
  [residuals ref]
  (t/is (v/delta-eq (:studentized residuals) (:studentized ref)))
  (t/is (v/delta-eq (get-in residuals [:standardized :deviance]) (get-in ref [:standardized :deviance])))
  (t/is (v/delta-eq (get-in residuals [:standardized :pearson]) (get-in ref [:standardized :pearson]))))

(defn- check-dose
  "3.1.16."
  [dose ref]
  (t/is (m/delta-eq (:dose dose) (:dose ref)))
  (t/is (m/delta-eq (:stderr dose) (:stderr ref))))

(defn- check-quantile-residuals
  "3.1.19."
  [qres ref]
  (t/is (v/delta-eq qres ref)))

(defn- glm-tests
  "§3.3. `ref-block` is an already-resolved {:model :analysis :extra} map.
  Dose is checked whenever fastmath's own fitted model has >1 coefficient AND
  the reference carries a (non-error) dose block -- mirrors the generator's
  own `(when (> (count (:coefficients model)) 1) ...)` gate exactly (fixing
  the original R-based `glm-tests`' `:coefficeints` typo, which had made its
  own dose comparison permanently vacuous)."
  ([ys xss ref-block] (glm-tests ys xss nil ref-block))
  ([ys xss options ref-block]
   (let [glm (sut/glm ys xss (merge {:epsilon 1.0e-16 :max-iters 100} options))
         analysis (sut/analysis glm)]
     (t/is (m/delta-eq (:intercept glm) (get-in ref-block [:model :intercept])))
     (t/is (v/delta-eq (:beta glm) (get-in ref-block [:model :beta])))
     (check-coefficients (:coefficients glm) (get-in ref-block [:model :coefficients]))
     (check-xtxinv (:xtxinv glm) (get-in ref-block [:model :xtxinv]))
     (check-df (:df glm) (get-in ref-block [:model :df]))
     (when-not (:no-ll? options)
       (check-ll (:ll glm) (get-in ref-block [:model :ll])))
     (check-fit-glm glm (:model ref-block))
     (when (:compare-deviance-null? options)
       (t/is (m/delta-eq (get-in glm [:deviance :null]) (get-in ref-block [:model :deviance :null]))))
     (check-residuals-glm (:residuals glm) (get-in ref-block [:model :residuals]))
     (check-weights (:weights glm) (get-in ref-block [:model :weights]))
     (when-not (:no-analysis? options)
       (check-correlation (:correlation analysis) (get-in ref-block [:analysis :correlation]))
       (check-analysis-residuals-glm (:residuals analysis) (get-in ref-block [:analysis :residuals]))
       (check-leverage (:leverage analysis) (get-in ref-block [:analysis :leverage]))
       (check-influence (:influence analysis) (get-in ref-block [:analysis :influence]) 1.0e-5))
     (when (> (count (:coefficients glm)) 1)
       (let [dose-ref (get-in ref-block [:extra :dose])]
         (when (and dose-ref (not (:error dose-ref)))
           (check-dose (sut/dose glm) dose-ref))))
     (when-let [qres-ref (get-in ref-block [:extra :quantile-residuals])]
       (check-quantile-residuals (sut/quantile-residuals glm) qres-ref))
     (when-let [predict-ref (get-in ref-block [:extra :predict])]
       (check-predict glm (:newdata-xss options) predict-ref)))))

(t/deftest dummy-data
  (let [ref (load-ref "dummy-data")]
    (glm-tests nys xss {:weights weights :family :binomial :newdata-xss new-xss} (:call-0 ref))
    (glm-tests nys xss {:weights weights :family :binomial :link :probit :newdata-xss new-xss} (:call-1 ref))
    (glm-tests nys xss {:weights weights :family :binomial :link :cloglog :newdata-xss new-xss} (:call-2 ref))
    (glm-tests nys xss {:weights weights :family :binomial :link :log :newdata-xss new-xss} (:call-3 ref))
    (glm-tests nys xss {:family :binomial :newdata-xss new-xss} (:call-4 ref))
    (glm-tests nys xss {:family :binomial :link :probit :newdata-xss new-xss} (:call-5 ref))
    (glm-tests nys xss {:family :binomial :link :cloglog :newdata-xss new-xss} (:call-6 ref))
    (glm-tests nys xss {:family :binomial :link :log :newdata-xss new-xss} (:call-7 ref))
    (glm-tests nys xss {:weights weights :family :binomial :intercept? false :newdata-xss new-xss} (:call-8 ref))
    (glm-tests nys xss {:weights weights :family :binomial :link :probit :intercept? false :newdata-xss new-xss}
                   (:call-9 ref))
    (glm-tests nys xss {:weights weights :family :binomial :link :cloglog :intercept? false :newdata-xss new-xss}
                   (:call-10 ref))
    (glm-tests nys xss {:family :binomial :intercept? false :newdata-xss new-xss} (:call-11 ref))
    (glm-tests nys xss {:family :binomial :link :probit :intercept? false :newdata-xss new-xss} (:call-12 ref))
    (glm-tests nys xss {:family :binomial :link :cloglog :intercept? false :newdata-xss new-xss} (:call-13 ref))
    (glm-tests nys xss {:family :binomial :transformer (fn [[a b c]] [(m/exp a) a b c]) :newdata-xss new-xss}
                   (:call-14 ref))))

(t/deftest gaussian-glm
  (let [ref (load-ref "gaussian-glm")]
    (glm-tests ys xss {:weights weights :newdata-xss new-xss} (:call-0 ref))
    (glm-tests ys xss {:weights weights :offset offset :newdata-xss (with-new-offset)} (:call-1 ref))
    (glm-tests ys xss {:weights weights :intercept? false :newdata-xss new-xss} (:call-2 ref))
    (glm-tests ys xss {:weights weights :intercept? false :offset offset :newdata-xss (with-new-offset)}
                   (:call-3 ref))
    (glm-tests ys xss {:newdata-xss new-xss} (:call-4 ref))
    (glm-tests ys xss {:offset offset :newdata-xss (with-new-offset)} (:call-5 ref))
    (glm-tests ys xss {:intercept? false :newdata-xss new-xss} (:call-6 ref))
    (glm-tests ys xss {:intercept? false :offset offset :newdata-xss (with-new-offset)} (:call-7 ref))))

(t/deftest gestation-data
  (let [ref (load-ref "gestation-data")
        {:keys [Weight Age Births]} (get-in ref [:inputs :columns])
        new-age [26.0 40.0]]
    (lm-tests Weight Age {:weights Births :newdata-xss new-age} (:call-0 ref))
    (lm-tests Weight Age {:newdata-xss new-age} (:call-1 ref))))

(t/deftest lungcap-data
  (let [ref (load-ref "lungcap-data")
        {:keys [FEV Age Ht Gender Smoke]} (get-in ref [:inputs :columns])
        logfev (mapv m/log FEV)
        gender-numeric (mapv #(if (= % :F) 0.0 1.0) Gender)
        {gender-f :F gender-m :M} (one-hot Gender [:F :M])
        ht-smoke (mapv * Ht Smoke)
        ;; new (Age, Ht, Gender, Smoke) rows, matching regression-ref-gen exactly
        new-age [8.0 15.0] new-ht [55.0 65.0]
        new-gender-numeric [0.0 1.0] new-gender-f [1.0 0.0] new-gender-m [0.0 1.0]
        new-smoke [0.0 1.0]
        new-ht-smoke (mapv * new-ht new-smoke)]
    (lm-tests logfev (map vector Age Ht gender-numeric Smoke)
                  {:newdata-xss (map vector new-age new-ht new-gender-numeric new-smoke)} (:call-0 ref))
    (lm-tests logfev (map vector Age Ht gender-f gender-m Smoke)
                  {:intercept? false
                   :newdata-xss (map vector new-age new-ht new-gender-f new-gender-m new-smoke)} (:call-1 ref))
    (lm-tests logfev (map vector Ht gender-numeric Smoke)
                  {:newdata-xss (map vector new-ht new-gender-numeric new-smoke)} (:call-2 ref))
    (lm-tests logfev (map vector gender-numeric Smoke)
                  {:newdata-xss (map vector new-gender-numeric new-smoke)} (:call-3 ref))
    (lm-tests logfev (map vector Age Smoke) {:newdata-xss (map vector new-age new-smoke)} (:call-4 ref))
    (lm-tests logfev (map vector Ht Smoke) {:newdata-xss (map vector new-ht new-smoke)} (:call-5 ref))
    (lm-tests logfev (map vector Ht Smoke ht-smoke)
                  {:newdata-xss (map vector new-ht new-smoke new-ht-smoke)} (:call-6 ref))))

(t/deftest dental-data
  (let [ref (load-ref "dental-data")
        {:keys [DMFT Sugar Indus]} (get-in ref [:inputs :columns])
        indus-bin (mapv #(if (= % :Ind) 0.0 1.0) Indus)
        sugar-indus (mapv * Sugar indus-bin)
        ;; new (Sugar, Indus) rows: Sugar=[10,50], Indus=[Ind,NonInd]
        new-sugar [10.0 50.0]
        new-indus-bin [0.0 1.0]
        new-sugar-indus (mapv * new-sugar new-indus-bin)
        new-xss (map vector new-sugar new-indus-bin new-sugar-indus)]
    (lm-tests DMFT (map vector Sugar indus-bin sugar-indus) {:newdata-xss new-xss} ref)))

(t/deftest cheese-data
  (let [ref (load-ref "cheese-data")
        {:keys [Taste Acetic H2S Lactic]} (get-in ref [:inputs :columns])
        lH2S (mapv m/log H2S)
        acetic-lH2S (mapv * Acetic lH2S)
        acetic-lactic (mapv * Acetic Lactic)
        lH2S-lactic (mapv * lH2S Lactic)
        triple (mapv * Acetic lH2S Lactic)
        ;; new (Acetic, H2S, Lactic) rows, matching regression-ref-gen exactly
        new-acetic [300.0 150.0]
        new-h2s [5000.0 100.0]
        new-lactic [1.3 1.0]
        new-lh2s (mapv m/log new-h2s)
        new-xss (map vector new-acetic new-lh2s new-lactic
