(t/deftest mammary-data
  (let [ref (load-ref "mammary-data")
        columns (get-in ref [:inputs :columns])
        n-outgrowths (:N.Outgrowths columns)
        n-assays (:N.Assays columns)
        n-cells (:N.Cells columns)
        ratio (mapv / n-outgrowths n-assays)
        lncells (mapv m/log n-cells)
        ;; new N.Cells=[50,90] (offset source)/N.Outgrowths=[5,10]
        new-loffset (mapv m/log [50.0 90.0])
        new-nout [5.0 10.0]]

    ;; only intercept and offset
    (glm-tests ratio :intercept {:family :binomial :link :cloglog
                                     :weights n-assays :offset lncells
                                     :newdata-xss (map vector new-loffset)}
                   (:call-0 ref))

    ;; intercept, offset, data point
    (glm-tests ratio n-outgrowths {:family :binomial :link :cloglog
                                       :weights n-assays :offset lncells
                                       :newdata-xss (map vector new-loffset new-nout)}
                   (:call-1 ref))

    ;; no intercept, offset, data point
    (glm-tests ratio n-outgrowths {:family :binomial :link :cloglog
                                       :weights n-assays :offset lncells
                                       :intercept? false :compare-deviance-null? false
                                       :newdata-xss (map vector new-loffset new-nout)}
                   (:call-2 ref))

    (glm-tests ratio lncells {:family :binomial :link :cloglog :weights n-assays
                                  :newdata-xss new-loffset}
                   (:call-3 ref))))

(t/deftest deposit-data
  (let [ref (load-ref "deposit-data")
        {:keys [Killed Number Deposit Insecticide]} (get-in ref [:inputs :columns])
        ratio (mapv / Killed Number)
        logdep (mapv m/log Deposit)
        {ins-a :A ins-b :B ins-c :C} (one-hot Insecticide [:A :B :C])
        ;; `sut/polynomial-transformer`, wrapped to poly-expand only the
        ;; log(Deposit) slot and pass the two Insecticide dummies through --
        ;; supersedes the old `add-poly`-based pre-expanded-columns approach
        ;; (see §2.4 above); unlike it, this is a genuine fitted closure
        ;; usable on *new* Deposit values, hence call-3's own newdata check below.
        poly-transformer (sut/polynomial-transformer logdep 2)
        deposit-poly-transformer (fn [[ld insb insc]] (into (poly-transformer [ld]) [insb insc]))
        model (sut/glm ratio (map vector Deposit ins-b ins-c) {:family :binomial :weights Number})
        model2 (sut/glm ratio (map vector Deposit ins-a ins-b ins-c)
                        {:family :binomial :weights Number :intercept? false})
        newdata (get-in ref [:extra :newdata])]
    (glm-tests ratio (map vector Deposit ins-b ins-c) {:family :binomial :weights Number} (:call-0 ref))
    (glm-tests ratio (map vector Deposit ins-a ins-b ins-c)
                   {:family :binomial :weights Number :intercept? false} (:call-1 ref))
    (glm-tests ratio (map vector logdep ins-a ins-b ins-c)
                   {:family :binomial :weights Number :intercept? false} (:call-2 ref))
    (t/is (v/delta-eq (map model (map vector newdata (repeat 0) (repeat 0)))
                      (get-in ref [:extra :predict-a :fit])))
    (t/is (v/delta-eq (map model (map vector newdata (repeat 1) (repeat 0)))
                      (get-in ref [:extra :predict-b :fit])))
    (t/is (v/delta-eq (map model (map vector newdata (repeat 0) (repeat 1)))
                      (get-in ref [:extra :predict-c :fit])))
    ;; stderr/confidence-interval, upgraded from the original bare-fit-only check
    (doseq [[level repeat0 repeat1] [[:predict-a (repeat 0) (repeat 0)]
                                      [:predict-b (repeat 1) (repeat 0)]
                                      [:predict-c (repeat 0) (repeat 1)]]
            :let [preds (map #(model % true) (map vector newdata repeat0 repeat1))
                  ref-block (get-in ref [:extra level])]]
      (t/is (v/delta-eq (map :stderr preds) (:stderr ref-block)))
      (t/is (v/delta-eq (mapcat :confidence-interval preds) (flatten (:confidence-interval ref-block)))))
    (t/are [id v] (v/delta-eq (:dose (sut/dose model2 0.5 id 0)) v)
      1 5.099708
      2 4.514714
      3 0.8443372)
    (glm-tests ratio (map vector logdep ins-b ins-c)
                   {:family :binomial :weights Number :transformer deposit-poly-transformer
                    :newdata-xss (get-in ref [:call-3 :extra :newdata-xss])}
                   (:call-3 ref))))

