(t/deftest danishlc-data
  (let [ref (load-ref "danishlc-data")
        {:keys [Cases Pop Age City AgeNum]} (get-in ref [:inputs :columns])
        loffset (v/log (seq Pop))
        {:keys [xss]} (mult-columns City Age)
        {age-5559 :55-59 age-6064 :60-64 age-6569 :65-69 age-7074 :70-74 age-gt74 :>74}
        (one-hot Age [:55-59 :60-64 :65-69 :70-74 :>74])
        age-xss (map vector age-5559 age-6064 age-6569 age-7074 age-gt74)
        ;; supersedes `add-poly` (§2.4 above) -- a fitted `:transformer`
        ;; closure, applied to the raw `AgeNum` column (like call-2's own xss)
        poly-transformer (sut/polynomial-transformer AgeNum 2)]
    ;; df = 0
    (glm-tests Cases xss {:family :poisson :offset loffset :no-analysis? true
                              :newdata-xss (get-in ref [:call-0 :extra :newdata-xss])} (:call-0 ref))
    (glm-tests Cases age-xss {:family :poisson :offset loffset
                                  :newdata-xss (get-in ref [:call-1 :extra :newdata-xss])} (:call-1 ref))
    (glm-tests Cases AgeNum {:family :poisson :offset loffset
                                 :newdata-xss (get-in ref [:call-2 :extra :newdata-xss])} (:call-2 ref))
    (glm-tests Cases AgeNum {:family :poisson :offset loffset :transformer poly-transformer
                                 :newdata-xss (get-in ref [:call-3 :extra :newdata-xss])} (:call-3 ref))))


